import numpy as np
from sklearn.tree import DecisionTreeRegressor
from sklearn.preprocessing import OneHotEncoder, StandardScaler

print("PRICE MODEL")

# Globals
model = DecisionTreeRegressor()
encoder = None
scaler = StandardScaler()
X_data = []
y_data = []

min_stock = 1
max_stock = 50

# Categorical value sets
categories = [
    ['digital', 'CD', 'cassette', 'vinyl'],
    ['Mint', 'Near Mint', 'Good', 'Fair', 'Poor'],
    ['Mint', 'Near Mint', 'Good', 'Fair', 'Poor'],
    ['331/3 RPM', '45 RPM', '78 RPM', 'None'],
    ['7 inch', '10 inch', '12 inch', 'None'],
    ['wav', 'mp3', 'None']
]

def _init():
    global encoder, scaler
    encoder = OneHotEncoder(categories=categories, handle_unknown='ignore')
    dummy = [[f, 'Mint', 'Mint', 'None', 'None', 'None'] for f in categories[0]]
    encoder.fit(dummy)
    scaler.fit([[min_stock], [max_stock]]) # range waarin de stock kan vallen

def _encode_input(format, media_condition, sleeve_condition, stock, rpm, size, file_kind):
    rpm = rpm if format == "vinyl" else "None"
    size = size if format == "vinyl" else "None"
    file_kind = file_kind if format == "digital" else "None"
    
    row = [[format, media_condition, sleeve_condition, rpm, size, file_kind]]
    encoded = encoder.transform(row).toarray()[0]  # Convert to dense and flatten
    stock_scaled = scaler.transform([[stock]])[0]  # Also flatten

#    print('encoded:', encoded)
#    print('stock_scaled:', stock_scaled)

    return np.concatenate([encoded, stock_scaled])


def train_general(format, media_condition, sleeve_condition, stock, rpm, size, file_kind, price):
    global X_data, y_data, model
    if encoder is None or scaler is None:
        _init()
    x = _encode_input(format, media_condition, sleeve_condition, stock, rpm, size, file_kind)
    X_data.append(x)
    y_data.append(price)
    model.fit(X_data, y_data)

def infer_general(format, media_condition, sleeve_condition, stock, rpm, size, file_kind):
    if not X_data:
        raise Exception("Model not trained yet.")
    x = _encode_input(format, media_condition, sleeve_condition, stock, rpm, size, file_kind)
    return (float(model.predict([x])[0]),)


